import{_ as i,I as n,c as o,o as t,a3 as a,b as s,w as l,a as E,J as d,a4 as A}from"./chunks/framework.BusRvirq.js";const _=JSON.parse('{"title":"[특허 백서] 모바일 제스처 분석 및 자연어 테스트 자동화 시스템","description":"모바일 터치 제스처를 무차원 정규화 벡터로 분석하여 자연어 테스트케이스로 변환하고 이종 디바이스에서 적응형 실행하는 기술 백서","frontmatter":{"title":"[특허 백서] 모바일 제스처 분석 및 자연어 테스트 자동화 시스템","shortTitle":"[21호] 모바일 제스처 & 자연어 QA","category":"원천기술 & 특허","sort":4,"description":"모바일 터치 제스처를 무차원 정규화 벡터로 분석하여 자연어 테스트케이스로 변환하고 이종 디바이스에서 적응형 실행하는 기술 백서","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/patents/21-mobile-gesture-nlp.html"}]]},"headers":[],"relativePath":"patents/21-mobile-gesture-nlp.md","filePath":"ko/patents/21-mobile-gesture-nlp.md","lastUpdated":1791239682000}'),B={name:"patents/21-mobile-gesture-nlp.md"};function C(c,e,g,h,D,m){const r=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="모바일-제스처-분석-및-자연어-테스트-자동화-시스템" tabindex="-1">모바일 제스처 분석 및 자연어 테스트 자동화 시스템 <a class="header-anchor" href="#모바일-제스처-분석-및-자연어-테스트-자동화-시스템" aria-label="Permalink to “모바일 제스처 분석 및 자연어 테스트 자동화 시스템”">​</a></h1><blockquote><p><strong>특허 출원 관리 번호</strong>: 제21호<br><strong>발명의 명칭</strong>: 모바일 단말 제스처 레코딩 및 네이티브 뷰 계층 분석을 통한 AI 기반 자연어 테스트케이스 생성 및 이종 모바일 디바이스 자동 실행 시스템 및 그 방법<br><strong>출원 관리 상태</strong>: 출원 준비 (우선심사 대상, 등록가능성 A등급 평가)<br><strong>연계 프로덕트</strong>: <code>SyncETA</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-해결하려는-기술적-과제" tabindex="-1">1. 해결하려는 기술적 과제 <a class="header-anchor" href="#_1-해결하려는-기술적-과제" aria-label="Permalink to “1. 해결하려는 기술적 과제”">​</a></h2><p>모바일 애플리케이션의 품질 검증(QA)은 기기별 화면 크기, 해상도(DPI), 운영체제(Android/iOS)의 극심한 파편화로 인해 상당한 비용이 소요됩니다.</p><p>종래의 모바일 테스트 자동화 도구(예: Appium, Espresso, XCUITest)는 다음과 같은 구조적 한계가 있었습니다:</p><ol><li><strong>해상도 및 레이아웃 종속성</strong>: 절대 픽셀 좌표 기반으로 기록된 제스처는 화면비가 다른 단말기에서 엉뚱한 위치를 터치하여 오동작 유발.</li><li><strong>식별자 변경에 따른 스크립트 파손</strong>: 앱 리팩토링이나 빌드 도구 변경으로 <code>resource-id</code>, <code>accessibility-id</code>가 변경되면 기존 테스트 스크립트 전면 무효화.</li><li><strong>높은 엔지니어링 진입 장벽</strong>: 복잡한 프로그래밍 코드로 테스트 스크립트를 작성해야 하므로 비개발자 QA 인력의 활용이 제한됨.</li></ol>',7)),(t(),s(A,null,{default:l(()=>[d(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Device%5B%22%EB%AA%A8%EB%B0%94%EC%9D%BC%20%EB%8B%A8%EB%A7%90%20%EC%A0%9C%EC%8A%A4%EC%B2%98%20%EC%9E%85%EB%A0%A5%20(%ED%83%AD%2C%20%EC%8A%A4%EC%99%80%EC%9D%B4%ED%94%84%20%EB%93%B1)%22%5D%20--%3E%20Rec%5B%220.0~1.0%20%EB%AC%B4%EC%B0%A8%EC%9B%90%20%EC%A0%95%EA%B7%9C%ED%99%94%20%EC%A2%8C%ED%91%9C%EA%B3%84%20%EB%B3%80%ED%99%98%22%5D%0A%20%20%20%20Device%20--%3E%20Tree%5B%22%EC%A0%91%EA%B7%BC%EC%84%B1%20%EB%85%B8%EB%93%9C%20%EA%B3%84%EC%B8%B5%20(Accessibility%20Tree)%20%EC%88%98%EC%A7%91%22%5D%0A%20%20%20%20Device%20--%3E%20Snap%5B%22%EC%8B%9C%EA%B0%81%20%EC%95%B5%EC%BB%A4%20(Visual%20Anchor)%20%EC%8A%A4%ED%81%AC%EB%A6%B0%EC%83%B7%20%EC%BA%A1%EC%B2%98%22%5D%0A%20%20%20%20Rec%20%26%20Tree%20%26%20Snap%20--%3E%20LLM%5B%22LLM%20%EA%B8%B0%EB%B0%98%20%EB%8F%84%EB%A9%94%EC%9D%B8%20%EC%98%A8%ED%86%A8%EB%A1%9C%EC%A7%80%20%EB%B6%84%EC%84%9D%22%5D%0A%20%20%20%20LLM%20--%3E%20NL_TC%5B%22%EC%A0%95%ED%98%95%ED%99%94%EB%90%9C%20%EC%9E%90%EC%97%B0%EC%96%B4%20%ED%85%8C%EC%8A%A4%ED%8A%B8%EC%BC%80%EC%9D%B4%EC%8A%A4%20%EC%83%9D%EC%84%B1%22%5D%0A%20%20%20%20NL_TC%20--%3E%20MCP%5B%22MCP%20%EA%B8%B0%EB%B0%98%20%EC%9D%B4%EC%A2%85%20%EB%94%94%EB%B0%94%EC%9D%B4%EC%8A%A4%20%ED%8C%9C%20%EB%B3%91%EB%A0%AC%20%EC%8B%A4%ED%96%89%22%5D%0A%20%20%20%20MCP%20--%3E%20Exec%7B%22UI%20%EC%8B%9D%EB%B3%84%EC%9E%90%20%EC%9C%A0%ED%9A%A8%EC%84%B1%20%EA%B2%80%EC%A6%9D%22%7D%0A%20%20%20%20Exec%20--%20%22%EC%A0%95%EC%83%81%20%EC%9D%BC%EC%B9%98%22%20--%3E%20Done%5B%22%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EC%99%84%EB%A3%8C%20%EB%B0%8F%20%EB%A6%AC%ED%8F%AC%ED%8A%B8%22%5D%0A%20%20%20%20Exec%20--%20%22ID%20%EB%B6%88%EC%9D%BC%EC%B9%98%2F%EB%B3%80%EA%B2%BD%20%EA%B0%90%EC%A7%80%22%20--%3E%20VLM%5B%22VLM%20%EB%93%80%EC%96%BC%20%ED%8D%BC%EC%85%89%EC%85%98%20%ED%93%A8%EC%A0%84%20%EA%B7%B8%EB%9D%BC%EC%9A%B4%EB%94%A9%20(%EC%9E%90%EA%B0%80%EC%B9%98%EC%9C%A0)%22%5D%0A%20%20%20%20VLM%20--%3E%20MCP%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-핵심-동작-메커니즘" tabindex="-1">2. 핵심 동작 메커니즘 <a class="header-anchor" href="#_2-핵심-동작-메커니즘" aria-label="Permalink to “2. 핵심 동작 메커니즘”">​</a></h2><p>본 발명은 사용자의 실제 모바일 단말 조작을 캡처하여 자연어 명세서로 변환하고, 이를 이종 기기에서 자율 적응형으로 재생하는 전 과정을 포함합니다.</p><h3 id="_1단계-제스처-벡터-정규화-및-다중-컨텍스트-수집" tabindex="-1">1단계: 제스처 벡터 정규화 및 다중 컨텍스트 수집 <a class="header-anchor" href="#_1단계-제스처-벡터-정규화-및-다중-컨텍스트-수집" aria-label="Permalink to “1단계: 제스처 벡터 정규화 및 다중 컨텍스트 수집”">​</a></h3><ul><li>사용자가 실기기 화면을 터치(탭, 롱프레스, 스와이프, 드래그 등)할 때 발생하는 입력 이벤트의 시계열 궤적, 접촉 면적, 압력 값을 수집합니다.</li><li>특정 기기의 픽셀 해상도에 종속되지 않도록 X, Y 좌표를 <strong>0.0부터 1.0 사이의 무차원 정규화 상대 좌표계 벡터</strong>로 변환합니다.</li><li>터치 발생 시점의 화면 이미지에서 특징 벡터와 바운딩 박스를 추출한 <strong>시각 앵커(Visual Anchor)</strong>를 생성하고, OS의 네이티브 접근성 노드 계층(Accessibility Node Hierarchy)을 병합합니다.</li></ul><h3 id="_2단계-llm-온톨로지-기반-자연어-테스트케이스-자동-생성" tabindex="-1">2단계: LLM 온톨로지 기반 자연어 테스트케이스 자동 생성 <a class="header-anchor" href="#_2단계-llm-온톨로지-기반-자연어-테스트케이스-자동-생성" aria-label="Permalink to “2단계: LLM 온톨로지 기반 자연어 테스트케이스 자동 생성”">​</a></h3><ul><li>수집된 복합 데이터(정규화 좌표, 노드 계층 텍스트, 시각적 컴포넌트 정보)를 대규모 언어 모델에 전달합니다.</li><li>모델은 모바일 상호작용 도메인 온톨로지 규칙을 참조하여, 개발자가 아닌 일반인도 즉시 이해할 수 있는 정형화된 테스트 단계(동작, 입력값, 기대 결과)로 자동 기술합니다: <ul><li><em>예시</em>: `&quot;로그인 화면에서 아이디 입력란에 &#39;testuser&#39;를 입력하고, 비밀번호를 입력한 뒤 &#39;로그인&#39; 버튼을 탭하여 메인 대시보드로 이동함을 확인한다.&quot;*</li></ul></li></ul><h3 id="_3단계-mcp-표준-프로토콜-기반-이종-디바이스-팜-적응형-실행" tabindex="-1">3단계: MCP 표준 프로토콜 기반 이종 디바이스 팜 적응형 실행 <a class="header-anchor" href="#_3단계-mcp-표준-프로토콜-기반-이종-디바이스-팜-적응형-실행" aria-label="Permalink to “3단계: MCP 표준 프로토콜 기반 이종 디바이스 팜 적응형 실행”">​</a></h3><ul><li>생성된 자연어 테스트케이스는 Model Context Protocol(MCP) 도구 인터페이스를 통해 원격에 분산 배치된 다수의 실기기(Android, iOS, 태블릿 등)로 브로드캐스팅됩니다.</li><li>각 기기의 해상도, 노치(Notch) 및 하단 홈 바(Safe Area) 여백에 맞춰 정규화 좌표가 대상 기기의 물리 픽셀로 실시간 매핑되어 정확한 지점을 조작합니다.</li></ul><h3 id="_4단계-vlm-듀얼-퍼셉션-퓨전-기반-자가치유-self-healing" tabindex="-1">4단계: VLM 듀얼 퍼셉션 퓨전 기반 자가치유 (Self-Healing) <a class="header-anchor" href="#_4단계-vlm-듀얼-퍼셉션-퓨전-기반-자가치유-self-healing" aria-label="Permalink to “4단계: VLM 듀얼 퍼셉션 퓨전 기반 자가치유 (Self-Healing)”">​</a></h3><ul><li>앱 버전 업데이트로 인해 네이티브 UI 식별자(ID)가 변경된 경우, Vision-Language Model(VLM)이 시각 앵커 이미지와 변경된 화면 간의 듀얼 퍼셉션 퓨전 그라운딩(IoU 0.10~0.30 임계치)을 수행합니다.</li><li>형태나 텍스트 위치가 유사한 대체 컴포넌트를 지능적으로 탐색하여 끊김 없이 테스트를 지속하며, 치유된 셀렉터 정보를 결과 리포트에 기록합니다.</li></ul><hr><h2 id="_3-선행기술-대비-차별성" tabindex="-1">3. 선행기술 대비 차별성 <a class="header-anchor" href="#_3-선행기술-대비-차별성" aria-label="Permalink to “3. 선행기술 대비 차별성”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">비교 항목</th><th style="text-align:left;">종래의 스크립트 도구 (Appium 등)</th><th style="text-align:left;">좌표 매크로 레코더</th><th style="text-align:left;">본 특허 시스템 (21호)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>테스트케이스 포맷</strong></td><td style="text-align:left;">프로그래밍 언어 코드 (Java, Python)</td><td style="text-align:left;">단순 픽셀 좌표 나열</td><td style="text-align:left;"><strong>사람이 읽는 자연어 명세서</strong></td></tr><tr><td style="text-align:left;"><strong>이기종 기기 호환성</strong></td><td style="text-align:left;">기기별 스크립트 분기 처리 필요</td><td style="text-align:left;">해상도 변경 시 오작동</td><td style="text-align:left;"><strong>무차원 정규화 상대 좌표계 변환</strong></td></tr><tr><td style="text-align:left;"><strong>UI 식별자 변경 시</strong></td><td style="text-align:left;">테스트 즉시 중단 및 실패 처리</td><td style="text-align:left;">복구 불가</td><td style="text-align:left;"><strong>VLM 듀얼 퍼셉션 기반 자가치유</strong></td></tr><tr><td style="text-align:left;"><strong>테스트 관리 접근성</strong></td><td style="text-align:left;">전문 테스트 엔지니어 필수</td><td style="text-align:left;">유지보수 불가능</td><td style="text-align:left;"><strong>일반 QA 및 기획자 즉시 활용 가능</strong></td></tr></tbody></table><hr><h2 id="_4-실측-성능-및-코드베이스-구현-증적" tabindex="-1">4. 실측 성능 및 코드베이스 구현 증적 <a class="header-anchor" href="#_4-실측-성능-및-코드베이스-구현-증적" aria-label="Permalink to “4. 실측 성능 및 코드베이스 구현 증적”">​</a></h2><p>국내외 주요 안드로이드/iOS 대표 단말기 12종(스마트폰 8종, 태블릿 4종) 대상 500회 회귀 테스트 실측 결과입니다:</p><ul><li><strong>크로스 디바이스 재생 정확도</strong>: 단일 기기 레코딩 후 이종 해상도 단말기 11종 재생 성공률 <strong>98.2%</strong> 기록.</li><li><strong>UI 변경 자가치유율</strong>: 네이티브 ID 변경 및 레이아웃 변형 상황에서 VLM 퓨전 그라운딩을 통한 자율 복구율 <strong>93.5%</strong> 달성.</li><li><strong>테스트케이스 작성 시간</strong>: 기존 코드 스크립트 작성 대비 자연어 변환을 통해 작성 소요 시간 <strong>약 78% 단축</strong>.</li></ul><h3 id="코드베이스-구현-위치-grounding" tabindex="-1">코드베이스 구현 위치 (Grounding) <a class="header-anchor" href="#코드베이스-구현-위치-grounding" aria-label="Permalink to “코드베이스 구현 위치 (Grounding)”">​</a></h3><ul><li><code>today-care/senior-app</code> 및 <code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileAgentService.java</code>: 모바일 에이전트 제어기</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileTcParserService.java</code>: 자연어 테스트케이스 파서 및 생성기</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteAdbService.java</code>: 원격 Android ADB 파이프라인</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteIosService.java</code>: 원격 iOS WebDriverAgent 연동기</li></ul>',20))])}const f=i(B,[["render",C]]);export{_ as __pageData,f as default};
